SELECT


WHERE v.deleted = 0
AND v.lifecycle_stage = 'PENDING_DELIVERY'

    AND v.vin LIKE CONCAT('%', #{query.vin}, '%')


    AND p.model_id = #{query.modelId}


    AND a.dealer_id = #{query.dealerId}




        AND dv.stage_status = #{query.stageStatus}


        AND 1 = 0


ORDER BY v.id DESC
